$("clr").onclick=()=>{pc.clearRect(0,0,pad.width,pad.height);inked=false;$("typed").value="";$("upl").value=""};
$("cancel").onclick=()=>{$("modal").classList.remove("show");if(!sig)setTool("edit")};
