  if(f){const im=new Image();await new Promise(r=>{im.onload=r;im.src=URL.createObjectURL(f)});
    cv=document.createElement("canvas");cv.width=im.width;cv.height=im.height;cv.getContext("2d").drawImage(im,0,0)}
  else if(txt){cv=document.createElement("canvas");let c=cv.getContext("2d");c.font=FNT;cv.width=Math.min(2400,c.measureText(txt).width+40);cv.height=260;
    c=cv.getContext("2d");c.font=FNT;c.fillStyle="#111";c.textBaseline="middle";c.fillText(txt,20,130)}
