/* ---- tool options, notes ---- */
const O={er:{m:"brush",s:24,auto:true,c:"#ffffff"},hl:{m:"mk",s:30,o:100,c:"#facc15"},pen:{s:5,o:100,c:"#111111"},nt:{c:"#f7d64a"}};
const OR={er:[4,120],hl:[4,80],pen:[1,40]},MODES={er:[["brush","Brush"],["obj","Objects"]],hl:[["mk","Marker"],["box","Box"]]};
const bc=document.createElement("div");bc.id="bcur";document.body.appendChild(bc);
function brushSize(){return tool==="er"&&O.er.m==="brush"?O.er.s:tool==="pen"?O.pen.s:tool==="hl"&&O.hl.m==="mk"?O.hl.s:0}
function syncOpts(t){
  bc.style.display="none";const o=O[t];if(!o)return;
  const ms=MODES[t],brush=!(t==="er"&&o.m==="obj"),box=t==="hl"&&o.m==="box",rg=OR[t];
  $("omodeW").classList.toggle("oh",!ms);$("omsep").classList.toggle("oh",!ms);
  if(ms){$("oM1").textContent=ms[0][1];$("oM2").textContent=ms[1][1];$("oM1").classList.toggle("on",o.m===ms[0][0]);$("oM2").classList.toggle("on",o.m===ms[1][0])}
  $("ocolW").classList.toggle("oh",!brush);$("ocol").value=o.c;
  $("oauto").classList.toggle("oh",t!=="er");$("oauto").classList.toggle("on",t==="er"&&!!o.auto);
  $("oszw").classList.toggle("oh",!rg||!brush||box);
  if(rg){$("osz").min=rg[0];$("osz").max=rg[1];$("osz").value=o.s;$("oszv").textContent=o.s+"px"}
  $("oopw").classList.toggle("oh",o.o==null);
  if(o.o!=null){$("oop").value=o.o;$("oopv").textContent=o.o+"%"}}
const _st2=setTool;setTool=function(t){_st2(t);syncOpts(t)};
[["oM1",0],["oM2",1]].forEach(([id,i])=>$(id).onclick=()=>{const ms=MODES[tool];if(!ms)return;O[tool].m=ms[i][0];syncOpts(tool)});
$("ocol").oninput=e=>{const o=O[tool];if(!o)return;o.c=e.target.value;if(tool==="er"){o.auto=false;$("oauto").classList.remove("on")}};
$("oauto").onclick=()=>{O.er.auto=!O.er.auto;$("oauto").classList.toggle("on",O.er.auto)};
$("osz").oninput=e=>{const o=O[tool];if(!o)return;o.s=+e.target.value;$("oszv").textContent=o.s+"px"};
$("oop").oninput=e=>{const o=O[tool];if(!o)return;o.o=+e.target.value;$("oopv").textContent=o.o+"%"};
